--
-- Name: users_user; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.users_user (
    id bigint NOT NULL,
    password character varying(128) NOT NULL,
    last_login timestamp with time zone,
    is_superuser boolean NOT NULL,
    username character varying(150) NOT NULL,
    first_name character varying(150) NOT NULL,
    last_name character varying(150) NOT NULL,
    email character varying(254) NOT NULL,
    is_staff boolean NOT NULL,
    date_joined timestamp with time zone NOT NULL,
    role character varying(20) NOT NULL,
    phone_number character varying(15),
    profile_picture character varying(100),
    is_verified boolean NOT NULL,
    otp_code character varying(6),
    is_active boolean NOT NULL,
    failed_login_attempts smallint NOT NULL,
    locked_until timestamp with time zone,
    mfa_attempts smallint NOT NULL,
    mfa_expires_at timestamp with time zone,
    mfa_hash character varying(128) NOT NULL,
    otp_attempts smallint NOT NULL,
    otp_expires_at timestamp with time zone,
    otp_hash character varying(128) NOT NULL,
    otp_sent_at timestamp with time zone,
    otp_used_at timestamp with time zone,
    token_version integer NOT NULL,
    CONSTRAINT users_user_failed_login_attempts_check CHECK ((failed_login_attempts >= 0)),
    CONSTRAINT users_user_mfa_attempts_check CHECK ((mfa_attempts >= 0)),
    CONSTRAINT users_user_otp_attempts_check CHECK ((otp_attempts >= 0)),
    CONSTRAINT users_user_token_version_check CHECK ((token_version >= 0))
);


ALTER TABLE public.users_user OWNER TO postgres;

